macro_rules! deps {
    () => {
        DiagnosticLevel!();
        DiagnosticCode!();
        DiagnosticSpan!();
    };
}

macro_rules! Diagnostic {
    () => {
        deps!();
        # [doc = " A diagnostic message generated by rustc"] # [derive (Debug , Clone , Serialize , Deserialize , PartialEq , Eq , Hash)] # [cfg_attr (feature = "builder" , derive (Builder))] # [non_exhaustive] # [cfg_attr (feature = "builder" , builder (pattern = "owned" , setter (into)))] pub struct Diagnostic { # [doc = " The error message of this diagnostic."] pub message : String , # [doc = " The associated error code for this diagnostic"] pub code : Option < DiagnosticCode > , # [doc = " \"error: internal compiler error\", \"error\", \"warning\", \"note\", \"help\""] pub level : DiagnosticLevel , # [doc = " A list of source code spans this diagnostic is associated with."] pub spans : Vec < DiagnosticSpan > , # [doc = " Associated diagnostic messages."] pub children : Vec < Diagnostic > , # [doc = " The message as rustc would render it"] pub rendered : Option < String > , }
    };
}

Diagnostic!()